code='''from collections import Counter, deque

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]
    seen = set()
    q = deque()
    for r in range(h):
        for c in range(w):
            if (r in (0, h-1) or c in (0, w-1)) and g[r][c] == bg and (r,c) not in seen:
                seen.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and g[nr][nc] == bg and (nr,nc) not in seen:
                seen.add((nr,nc)); q.append((nr,nc))
    enclosed = [(r,c) for r in range(h) for c in range(w) if g[r][c] == bg and (r,c) not in seen]
    if enclosed:
        for r,c in enclosed: g[r][c] = 4
        return g
    # If there is no enclosed background, mark the interior isolated square object.
    colors = [v for v in Counter(v for row in g for v in row) if v != bg]
    for color in colors:
        seen_obj=set()
        for r in range(h):
            for c in range(w):
                if g[r][c] != color or (r,c) in seen_obj: continue
                comp=[]; q=deque([(r,c)]); seen_obj.add((r,c))
                while q:
                    x,y=q.popleft(); comp.append((x,y))
                    for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                        if 0<=nx<h and 0<=ny<w and g[nx][ny]==color and (nx,ny) not in seen_obj:
                            seen_obj.add((nx,ny)); q.append((nx,ny))
                rs=[x for x,y in comp]; cs=[y for x,y in comp]
                hh=max(rs)-min(rs)+1; ww=max(cs)-min(cs)+1
                if hh==ww and len(comp)==hh*ww and min(rs)>0 and max(rs)<h-1 and min(cs)>0 and max(cs)<w-1:
                    for x,y in comp: g[x][y]=4
                    return g
    return g
'''
